const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,experiment='matched';const number=x=>Number(String(x).replaceAll(',','')),fmt=(x,n=1)=>Number(x).toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n}),signed=(x,n=2)=>(x>=0?'+':'')+fmt(x,n);
const card=(name,value,detail)=>`<div class="metric"><span>${name}</span><strong>${value}</strong><small>${detail}</small></div>`;
function table(headers,rows){return `<div class="results-card study-table"><table><thead><tr>${headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((c,i)=>`<${i?'td':'th'} ${i?'':'scope="row"'}>${esc(c)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function comparison(title,rows,unit,note){const max=Math.max(...rows.map(r=>r[1]),1);return `<section class="results-card comparison-card"><div><h3>${title}</h3><p>${note}</p></div>${rows.map(([label,value])=>`<div class="comparison-row"><span>${label}</span><div><i style="width:${100*value/max}%"></i></div><strong>${fmt(value)} <small>${unit}</small></strong></div>`).join('')}</section>`;}
function render(){if(!data)return;const key=$('#case').value+'_'+$('#period').value,scope=($('#case').value==='CORRIDOR'?'Network':$('#case').value)+' '+$('#period').value,study=data[experiment],tables=study.tables;
 $('#matched').setAttribute('aria-pressed',String(experiment==='matched'));$('#emergency').setAttribute('aria-pressed',String(experiment==='emergency'));
 if(experiment==='matched'){
  const effect=tables.paired.find(r=>r.case===key),travel=tables.table8.slice(1).filter(r=>r[0]===scope),accounting=tables.table9.slice(1).filter(r=>r[0]===scope),queues=tables.table10.slice(1).filter(r=>r[0]===scope);
  $('#results').innerHTML=`<div class="result-heading"><div><span class="eyebrow">48 RUNS / FIXED VERSUS LOCAL RULE</span><h2>${esc(scope)} · Traffic control</h2><p>600 s warmup + 3,600 s study hour · demand factor 1.00 · seeds 7100 / 7101 / 7102</p></div><span class="quality-tag">Recorded SUMO</span></div><div class="metrics">${card('All-demand accrued-time reduction',fmt(effect.all_demand_time_reduction_percent,2)+'%',`± ${fmt(effect.all_demand_time_reduction_sd,2)}% sample SD · primary measure`)}${card('Study-cohort completion change',signed(effect.completion_change_pp)+' pp','Includes all scheduled study journeys')}${card('Matched seeds','3','Same demand and seed in each control pair')}</div><div class="study-comparisons">${comparison('Accrued time per scheduled vehicle',accounting.map(r=>[r[1],number(r[6])]),'s','All scheduled demand; includes active and not-inserted trips at the common cutoff.')}${comparison('Travel time of completed trips',travel.map(r=>[r[1],number(r[2])]),'s','Completed trips only. This is a secondary measure and excludes unfinished trips.')}</div><h3 class="section-title">Trip accounting at the common cutoff</h3>${table(tables.table9[0].slice(1),accounting.map(r=>r.slice(1)))}<p class="study-note">Counts are means across three seeds, so fractional values are expected. Accrued time is a lower bound on eventual journey time. Large insertion backlogs remain.</p><details class="source-detail"><summary>Travel, stopping and queue details</summary>${table(tables.table8[0].slice(1),travel.map(r=>r.slice(1)))}${table(tables.table10[0].slice(1),queues.map(r=>r.slice(1)))}</details><div class="study-limit"><strong>Unfavorable results are retained.</strong> A.C. Cortes has higher P95 travel and slightly lower completion; A. Soriano PM has more stop episodes. The candidate is a transparent local puck-score rule, not trained RL or a demonstrated exact max-pressure implementation. No C2C coordination overrides were used.</div>`;
 }else{
  const pair=tables.pairs.find(p=>p.case===key&&p.candidate==='priority20'&&p.baseline==='local'),travel=tables.table11.find(r=>r[0]===scope),request=tables.table12.find(r=>r[0]===scope),sensitivity=tables.table13.slice(1).filter(r=>r[0]===scope);
  $('#results').innerHTML=`<div class="result-heading"><div><span class="eyebrow">72 MAIN RUNS + 6 CAP SENSITIVITIES</span><h2>${esc(scope)} · Emergency beacon</h2><p>Identical controlled probe per arm · 20 s encounter cap · seeds 7300 / 7301 / 7302</p></div><span class="quality-tag">Ideal packet inputs</span></div><div class="metrics">${card('Probe time saved versus local',fmt(pair.EV_seconds_saved)+' s',`± ${fmt(pair.EV_seconds_saved_sd)} s sample SD · scheduled-start total`)}${card('Ordinary accrued-time change',signed(pair.ordinary_time_cost_percent)+'%','Positive means a cost to ordinary traffic')}${card('Ordinary completion change',signed(pair.ordinary_completion_change_pp)+' pp','Beacon minus local, without beacon')}</div><div class="study-comparisons">${comparison('On-road emergency-probe travel',[['Fixed',number(travel[4])],['Local',number(travel[5])],['Local + beacon',number(travel[6])]],'s','Actual insertion to arrival. Excludes insertion delay.')}${comparison('Scheduled-start to arrival',[['Fixed',number(travel[1])],['Local',number(travel[2])],['Local + beacon',number(travel[3])]],'s','Includes insertion delay. These are simulation totals, not clinical dispatch response times.')}</div><h3 class="section-title">Request and ordinary-traffic outcomes</h3>${table(tables.table12[0].slice(1),[request.slice(1)])}<p class="study-note">F / L / P = fixed / local without beacon / local with 20 s beacon. Passage means front stop-line crossing while priority is active, not full rear clearance. Network request metrics pool nine encounters.</p>${sensitivity.length?`<h3 class="section-title">Predeclared 60 s sensitivity · A. Soriano</h3>${table(tables.table13[0].slice(1),sensitivity.map(r=>r.slice(1)))}<p class="study-note">One PM seed worsened with the longer cap. This does not establish a universal optimal duration.</p>`:''}<div class="study-limit"><strong>The short cap often expires before passage.</strong> Isolated J2/J3 AM beacon totals worsen relative to local control; A.C. Cortes retains substantial loading delays. One route, ideal GNSS/packet delivery and no competing emergency vehicles were tested. Local safety/clearance guards and synthetic identity fields are not physical radio or cryptographic verification.</div>`;
 }
}
$('#matched').onclick=()=>{experiment='matched';render();};$('#emergency').onclick=()=>{experiment='emergency';render();};$('#case').onchange=render;$('#period').onchange=render;
$('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='PASADA_recorded_SUMO_results_2026-11-01.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{const r=await fetch('./results.json');if(!r.ok)throw Error('Recorded results are unavailable.');data=await r.json();if(data.schema!=='pasada.study-results/0.1.0')throw Error('Unsupported results release.');render();$('#download').disabled=false;}catch(e){$('#results').textContent=e.message;}
